36	struct BlendArg : Number
37	{
38	  inline void init (void)
39	  {
40	    Number::init ();
41	    deltas.init ();
42	  }
43	
44	  inline void fini (void)
45	  {
46	    Number::fini ();
47	    deltas.fini_deep ();
48	  }
49	
50	  inline void set_int (int v) { reset_blends (); Number::set_int (v); }
51	  inline void set_fixed (int32_t v) { reset_blends (); Number::set_fixed (v); }
52	  inline void set_real (float v) { reset_blends (); Number::set_real (v); }
53	
54	  inline void set_blends (unsigned int numValues_, unsigned int valueIndex_,
55				  unsigned int numBlends, const BlendArg *blends_)
56	  {
57	    numValues = numValues_;
58	    valueIndex = valueIndex_;
59	    deltas.resize (numBlends);
60	    for (unsigned int i = 0; i < numBlends; i++)
61	      deltas[i] = blends_[i];
62	  }
63	
64	  inline bool blending (void) const { return deltas.len > 0; }
65	  inline void reset_blends (void)
66	  {
67	    numValues = valueIndex = 0;
68	    deltas.resize (0);
69	  }
70	
71	  unsigned int numValues;
72	  unsigned int valueIndex;
73	  hb_vector_t<Number> deltas;
74	};
75	
76	typedef InterpEnv<BlendArg> BlendInterpEnv;
77	typedef BiasedSubrs<CFF2Subrs>   CFF2BiasedSubrs;
78	
79	struct CFF2CSInterpEnv : CSInterpEnv<BlendArg, CFF2Subrs>
80	{
81	  template <typename ACC>
82	  inline void init (const ByteStr &str, ACC &acc, unsigned int fd,
83			    const int *coords_=nullptr, unsigned int num_coords_=0)
84	  {
85	    SUPER::init (str, *acc.globalSubrs, *acc.privateDicts[fd].localSubrs);
86	
87	    coords = coords_;
88	    num_coords = num_coords_;
89	    varStore = acc.varStore;
90	    seen_blend = false;
91	    seen_vsindex_ = false;
92	    scalars.init ();
93	    do_blend = (coords != nullptr) && num_coords && (varStore != &Null(CFF2VariationStore));
94	    set_ivs (acc.privateDicts[fd].ivs);
95	  }
96	
97	  inline void fini (void)
98	  {
99	    scalars.fini ();
100	    SUPER::fini ();
101	  }
102	
103	  inline OpCode fetch_op (void)
104	  {
105	    if (this->substr.avail ())
106	      return SUPER::fetch_op ();
107	
108	    /* make up return or endchar op */
109	    if (this->callStack.is_empty ())
110	      return OpCode_endchar;
111	    else
112	      return OpCode_return;
113	  }
114	
115	  inline const BlendArg& eval_arg (unsigned int i)
116	  {
117	    BlendArg  &arg = argStack[i];
118	    blend_arg (arg);
119	    return arg;
120	  }
121	
122	  inline const BlendArg& pop_arg (void)
123	  {
124	    BlendArg  &arg = argStack.pop ();
125	    blend_arg (arg);
126	    return arg;
127	  }
128	
129	  inline void process_blend (void)
130	  {
131	    if (!seen_blend)
132	    {
133	      region_count = varStore->varStore.get_region_index_count (get_ivs ());
134	      if (do_blend)
135	      {
136		scalars.resize (region_count);
137		varStore->varStore.get_scalars (get_ivs (),
138						(int *)coords, num_coords,
139						&scalars[0], region_count);
140	      }
141	      seen_blend = true;
142	    }
143	  }
144	
145	  inline void process_vsindex (void)
146	  {
147	    unsigned int  index = argStack.pop_uint ();
148	    if (unlikely (seen_vsindex () || seen_blend))
149	    {
150	      set_error ();
151	    }
152	    else
153	    {
154	      set_ivs (index);
155	    }
156	    seen_vsindex_ = true;
157	  }
158	
159	  inline unsigned int get_region_count (void) const { return region_count; }
160	  inline void	 set_region_count (unsigned int region_count_) { region_count = region_count_; }
161	  inline unsigned int get_ivs (void) const { return ivs; }
162	  inline void	 set_ivs (unsigned int ivs_) { ivs = ivs_; }
163	  inline bool	 seen_vsindex (void) const { return seen_vsindex_; }
164	
165	  protected:
166	  inline void blend_arg (BlendArg &arg)
167	  {
168	    if (do_blend && arg.blending ())
169	    {
170	      if (likely (scalars.len == arg.deltas.len))
171	      {
172		float v = arg.to_real ();
173		for (unsigned int i = 0; i < scalars.len; i++)
174		{
175		  v += scalars[i] * arg.deltas[i].to_real ();
176		}
177		arg.set_real (v);
178		arg.deltas.resize (0);
179	      }
180	    }
181	  }
182	
183	  protected:
184	  const int     *coords;
185	  unsigned int  num_coords;
186	  const	 CFF2VariationStore *varStore;
187	  unsigned int  region_count;
188	  unsigned int  ivs;
189	  hb_vector_t<float>  scalars;
190	  bool	  do_blend;
191	  bool	  seen_vsindex_;
192	  bool	  seen_blend;
193	
194	  typedef CSInterpEnv<BlendArg, CFF2Subrs> SUPER;
195	};
196	template <typename OPSET, typename PARAM, typename PATH=PathProcsNull<CFF2CSInterpEnv, PARAM> >
197	struct CFF2CSOpSet : CSOpSet<BlendArg, OPSET, CFF2CSInterpEnv, PARAM, PATH>
198	{
199	  static inline void process_op (OpCode op, CFF2CSInterpEnv &env, PARAM& param)
200	  {
201	    switch (op) {
202	      case OpCode_callsubr:
203	      case OpCode_callgsubr:
204		/* a subroutine number shoudln't be a blended value */
205		if (unlikely (env.argStack.peek ().blending ()))
206		{
207		  env.set_error ();
208		  break;
209		}
210		SUPER::process_op (op, env, param);
211		break;
212	
213	      case OpCode_blendcs:
214		OPSET::process_blend (env, param);
215		break;
216	
217	      case OpCode_vsindexcs:
218		if (unlikely (env.argStack.peek ().blending ()))
219		{
220		  env.set_error ();
221		  break;
222		}
223		OPSET::process_vsindex (env, param);
224		break;
225	
226	      default:
227		SUPER::process_op (op, env, param);
228	    }
229	  }
230	
231	  static inline void process_blend (CFF2CSInterpEnv &env, PARAM& param)
232	  {
233	    unsigned int n, k;
234	
235	    env.process_blend ();
236	    k = env.get_region_count ();
237	    n = env.argStack.pop_uint ();
238	    /* copy the blend values into blend array of the default values */
239	    unsigned int start = env.argStack.get_count () - ((k+1) * n);
240	    for (unsigned int i = 0; i < n; i++)
241	      env.argStack[start + i].set_blends (n, i, k, &env.argStack[start + n + (i * k)]);
242	
243	    /* pop off blend values leaving default values now adorned with blend values */
244	    env.argStack.pop (k * n);
245	  }
246	
247	  static inline void process_vsindex (CFF2CSInterpEnv &env, PARAM& param)
248	  {
249	    env.process_vsindex ();
250	    env.clear_args ();
251	  }
252	
253	  private:
254	  typedef CSOpSet<BlendArg, OPSET, CFF2CSInterpEnv, PARAM, PATH>  SUPER;
255	};
256	
257	template <typename OPSET, typename PARAM>
258	struct CFF2CSInterpreter : CSInterpreter<CFF2CSInterpEnv, OPSET, PARAM> {};
259	
260	} /* namespace CFF */
261	
262	#endif /* HB_CFF2_INTERP_CS_HH */
