218	struct Number
219	{
220	  inline void init (void)
221	  { set_int (0); }
222	  inline void fini (void)
223	  {}
224	
225	  inline void set_int (int v)	   { format = NumInt; u.int_val = v; }
226	  inline int to_int (void) const	{ return is_int ()? u.int_val: (int)to_real (); }
227	  inline void set_fixed (int32_t v)     { format = NumFixed; u.fixed_val = v; }
228	  inline int32_t to_fixed (void) const
229	  {
230	    if (is_fixed ())
231	      return u.fixed_val;
232	    else if (is_real ())
233	      return (int32_t)(u.real_val * 65536.0f);
234	    else
235	      return (int32_t)(u.int_val << 16);
236	  }
237	  inline void set_real (float v)	{ format = NumReal; u.real_val = v; }
238	  inline float to_real (void) const
239	  {
240	    if (is_real ())
241	      return u.real_val;
242	    if (is_fixed ())
243	      return u.fixed_val / 65536.0f;
244	    else
245	      return (float)u.int_val;
246	  }
247	
248	  inline int ceil (void) const
249	  {
250	    switch (format)
251	    {
252	      default:
253	      case NumInt:
254		return u.int_val;
255	      case NumFixed:
256		return (u.fixed_val + 0xFFFF) >> 16;
257	      case NumReal:
258		return (int)ceilf (u.real_val);
259	    }
260	  }
261	
262	  inline int floor (void) const
263	  {
264	    switch (format)
265	    {
266	      default:
267	      case NumInt:
268		return u.int_val;
269	      case NumFixed:
270		return u.fixed_val >> 16;
271	      case NumReal:
272		return (int)floorf (u.real_val);
273	    }
274	  }
275	
276	  inline bool in_int_range (void) const
277	  {
278	    if (is_int ())
279	      return true;
280	    if (is_fixed () && ((u.fixed_val & 0xFFFF) == 0))
281	      return true;
282	    else
283	      return ((float)(int16_t)to_int () == u.real_val);
284	  }
285	
286	  inline bool operator > (const Number &n) const
287	  {
288	    switch (format)
289	    {
290	      default:
291	      case NumInt: return u.int_val > n.to_int ();
292	      case NumFixed: return u.fixed_val > n.to_fixed ();
293	      case NumReal: return u.real_val > n.to_real ();
294	    }
295	  }
296	
297	  inline bool operator < (const Number &n) const
298	  { return n > *this; }
299	
300	  inline bool operator >= (const Number &n) const
301	  { return ! (*this < n); }
302	
303	  inline bool operator <= (const Number &n) const
304	  { return ! (*this > n); }
305	
306	  inline const Number &operator += (const Number &n)
307	  {
308	    if (format == NumReal || n.format == NumReal)
309	      set_real (to_real () + n.to_real ());
310	    else if (format == NumFixed || n.format == NumFixed)
311	      set_fixed (to_fixed () + n.to_fixed ());
312	    else
313	      set_int (to_int () + n.to_int ());
314	
315	    return *this;
316	  }
317	
318	protected:
319	  enum NumFormat {
320	    NumInt,
321	    NumFixed,
322	    NumReal
323	  };
324	  NumFormat  format;
325	  union {
326	    int     int_val;
327	    int32_t fixed_val;
328	    float   real_val;
329	  } u;
330	
331	  inline bool  is_int (void) const { return format == NumInt; }
332	  inline bool  is_fixed (void) const { return format == NumFixed; }
333	  inline bool  is_real (void) const { return format == NumReal; }
334	};
