336	/* byte string */
337	struct UnsizedByteStr : UnsizedArrayOf <HBUINT8>
338	{
339	  // encode 2-byte int (Dict/CharString) or 4-byte int (Dict)
340	  template <typename INTTYPE, int minVal, int maxVal>
341	  inline static bool serialize_int (hb_serialize_context_t *c, OpCode intOp, int value)
342	  {
343	    TRACE_SERIALIZE (this);
344	
345	    if (unlikely ((value < minVal || value > maxVal)))
346	      return_trace (false);
347	
348	    HBUINT8 *p = c->allocate_size<HBUINT8> (1);
349	    if (unlikely (p == nullptr)) return_trace (false);
350	    p->set (intOp);
351	
352	    INTTYPE *ip = c->allocate_size<INTTYPE> (INTTYPE::static_size);
353	    if (unlikely (ip == nullptr)) return_trace (false);
354	    ip->set ((unsigned int)value);
355	
356	    return_trace (true);
357	  }
358	
359	  inline static bool serialize_int4 (hb_serialize_context_t *c, int value)
360	  { return serialize_int<HBUINT32, 0, 0x7FFFFFFF> (c, OpCode_longintdict, value); }
361	
362	  inline static bool serialize_int2 (hb_serialize_context_t *c, int value)
363	  { return serialize_int<HBUINT16, 0, 0x7FFF> (c, OpCode_shortint, value); }
364	
365	  /* Defining null_size allows a Null object may be created. Should be safe because:
366	   * A descendent struct Dict uses a Null pointer to indicate a missing table,
367	   * checked before access.
368	   * ByteStr, a wrapper struct pairing a byte pointer along with its length, always
369	   * checks the length before access. A Null pointer is used as the initial pointer
370	   * along with zero length by the default ctor.
371	   */
372	  DEFINE_SIZE_MIN(0);
373	};
