375	struct ByteStr
376	{
377	  inline ByteStr (void)
378	    : str (&Null(UnsizedByteStr)), len (0) {}
379	  inline ByteStr (const UnsizedByteStr& s, unsigned int l)
380	    : str (&s), len (l) {}
381	  inline ByteStr (const char *s, unsigned int l=0)
382	    : str ((const UnsizedByteStr *)s), len (l) {}
383	  /* sub-string */
384	  inline ByteStr (const ByteStr &bs, unsigned int offset, unsigned int len_)
385	  {
386	    str = (const UnsizedByteStr *)&bs.str[offset];
387	    len = len_;
388	  }
389	
390	  inline bool sanitize (hb_sanitize_context_t *c) const { return str->sanitize (c, len); }
391	
392	  inline const HBUINT8& operator [] (unsigned int i) const {
393	    assert (str && (i < len));
394	    return (*str)[i];
395	  }
396	
397	  inline bool serialize (hb_serialize_context_t *c, const ByteStr &src)
398	  {
399	    TRACE_SERIALIZE (this);
400	    HBUINT8 *dest = c->allocate_size<HBUINT8> (src.len);
401	    if (unlikely (dest == nullptr))
402	      return_trace (false);
403	    memcpy (dest, src.str, src.len);
404	    return_trace (true);
405	  }
406	
407	  inline unsigned int get_size (void) const { return len; }
408	
409	  inline bool check_limit (unsigned int offset, unsigned int count) const
410	  { return (offset + count <= len); }
411	
412	  const UnsizedByteStr *str;
413	  unsigned int len;
414	};
