467	/* stack */
468	template <typename ELEM, int LIMIT>
469	struct Stack
470	{
471	  inline void init (void)
472	  {
473	    error = false;
474	    count = 0;
475	    elements.init ();
476	    elements.resize (kSizeLimit);
477	    for (unsigned int i = 0; i < elements.len; i++)
478	      elements[i].init ();
479	  }
480	
481	  inline void fini (void)
482	  {
483	    elements.fini_deep ();
484	  }
485	
486	  inline ELEM& operator [] (unsigned int i)
487	  {
488	    if (unlikely (i >= count)) set_error ();
489	    return elements[i];
490	  }
491	
492	  inline void push (const ELEM &v)
493	  {
494	    if (likely (count < elements.len))
495	      elements[count++] = v;
496	    else
497	      set_error ();
498	  }
499	
500	  inline ELEM &push (void)
501	  {
502	    if (likely (count < elements.len))
503	      return elements[count++];
504	    else
505	    {
506	      set_error ();
507	      return Crap(ELEM);
508	    }
509	  }
510	
511	  inline ELEM& pop (void)
512	  {
513	    if (likely (count > 0))
514	      return elements[--count];
515	    else
516	    {
517	      set_error ();
518	      return Crap(ELEM);
519	    }
520	  }
521	
522	  inline void pop (unsigned int n)
523	  {
524	    if (likely (count >= n))
525	      count -= n;
526	    else
527	      set_error ();
528	  }
529	
530	  inline const ELEM& peek (void)
531	  {
532	    if (likely (count > 0))
533	      return elements[count-1];
534	    else
535	    {
536	      set_error ();
537	      return Null(ELEM);
538	    }
539	  }
540	
541	  inline void unpop (void)
542	  {
543	    if (likely (count < elements.len))
544	      count++;
545	    else
546	      set_error ();
547	  }
548	
549	  inline void clear (void) { count = 0; }
550	
551	  inline bool in_error (void) const { return (error || elements.in_error ()); }
552	  inline void set_error (void) { error = true; }
553	
554	  inline unsigned int get_count (void) const { return count; }
555	  inline bool is_empty (void) const { return count == 0; }
556	
557	  static const unsigned int kSizeLimit = LIMIT;
558	
559	  protected:
560	  bool error;
561	  unsigned int count;
562	  hb_vector_t<ELEM, kSizeLimit> elements;
563	};
