615	  {
616	    if (unlikely (!substr.avail (4)))
617	      return false;
618	    push_fixed ((int32_t)*(const HBUINT32*)&substr[0]);
619	    substr.inc (4);
620	    return true;
621	  }
622	
623	  private:
624	  typedef Stack<ARG, 513> S;
625	};
