719	  inline void set_error (void) { error = true; }
720	
721	  inline OpCode fetch_op (void)
722	  {
723	    OpCode  op = OpCode_Invalid;
724	    if (unlikely (!substr.avail ()))
725	      return OpCode_Invalid;
726	    op = (OpCode)(unsigned char)substr[0];
727	    if (op == OpCode_escape) {
728	      if (unlikely (!substr.avail ()))
729		return OpCode_Invalid;
730	      op = Make_OpCode_ESC(substr[1]);
731	      substr.inc ();
732	    }
733	    substr.inc ();
734	    return op;
