742	  inline ARG& pop_arg (void)
743	  {
744	    return argStack.pop ();
745	  }
746	
747	  inline void pop_n_args (unsigned int n)
748	  {
749	    assert (n <= argStack.get_count ());
750	    argStack.pop (n);
751	  }
752	
753	  inline void clear_args (void)
754	  {
755	    pop_n_args (argStack.get_count ());
756	  }
757	
758	  SubByteStr    substr;
759	  ArgStack<ARG> argStack;
760	  protected:
761	  bool	  error;
762	};
763	
764	typedef InterpEnv<> NumInterpEnv;
765	
766	template <typename ARG=Number>
767	struct OpSet
768	{
769	  static inline void process_op (OpCode op, InterpEnv<ARG>& env)
770	  {
771	    switch (op) {
772	      case OpCode_shortint:
773		env.argStack.push_int ((int16_t)((env.substr[0] << 8) | env.substr[1]));
774		env.substr.inc (2);
775		break;
776	
777	      case OpCode_TwoBytePosInt0: case OpCode_TwoBytePosInt1:
778	      case OpCode_TwoBytePosInt2: case OpCode_TwoBytePosInt3:
779		env.argStack.push_int ((int16_t)((op - OpCode_TwoBytePosInt0) * 256 + env.substr[0] + 108));
780		env.substr.inc ();
781		break;
782	
783	      case OpCode_TwoByteNegInt0: case OpCode_TwoByteNegInt1:
784	      case OpCode_TwoByteNegInt2: case OpCode_TwoByteNegInt3:
785		env.argStack.push_int ((int16_t)(-(op - OpCode_TwoByteNegInt0) * 256 - env.substr[0] - 108));
786		env.substr.inc ();
787		break;
788	
789	      default:
790		/* 1-byte integer */
791		if (likely ((OpCode_OneByteIntFirst <= op) && (op <= OpCode_OneByteIntLast)))
792		{
793		  env.argStack.push_int ((int)op - 139);
794		} else {
795		  /* invalid unknown operator */
796		  env.clear_args ();
797		  env.set_error ();
798		}
799		break;
800	    }
801	  }
802	};
803	
804	template <typename ENV>
805	struct Interpreter {
806	
807	  inline ~Interpreter(void) { fini (); }
808	
809	  inline void fini (void) { env.fini (); }
810	
811	  ENV env;
812	};
813	
814	} /* namespace CFF */
815	
816	#endif /* HB_CFF_INTERP_COMMON_HH */
817

